INSERT INTO providers (id,slug,listing_type,name,description,website_url,source_url,listing_status,claim_status,origin,provider_classification)
SELECT 'independent-elynn-diamond','elynn-diamond-studio-independent-elynn-diamond','coach','Elynn Diamond Studio','Elynn Diamond offers private singing lessons and one-to-one vocal coaching in New York City, with online sessions available. Vocal coach and holistic arts life coach; works with professional and non-professional singers.','https://elynndiamond.com/','https://elynndiamond.com/','published','unclaimed','seeded','independent_teacher'
WHERE NOT EXISTS (SELECT 1 FROM providers WHERE lower(trim(name))=lower(trim('Elynn Diamond Studio')) AND lower(trim(website_url))=lower(trim('https://elynndiamond.com/')));
